import subprocessimport timeimport socketimport reimport shutilimport osimport copyimport sslimport randomimport mathimport ipaddressimport concurrent.futuresfrom dataclasses import dataclass, fieldfrom typing import List, Generator, Callable, Optional, Tuple, Set, Dictdef is_valid_public_ip(ip_str: str) -> bool:    """Проверяет, что IP адрес является публичным (не loopback, private, bogon)."""    try:        ip = ipaddress.ip_address(ip_str)        return not (ip.is_private or ip.is_loopback or ip.is_multicast or ip.is_unspecified or ip.is_reserved)    except ValueError:        return Falsedef is_valid_domain(domain_str: str) -> bool:    """Проверяет синтаксическую валидность доменного имени."""    if not domain_str or len(domain_str) > 253:        return False    if domain_str.startswith('.') or domain_str.endswith('.'):        return False    if not domain_str.replace('.', '').isdigit() and ('.' in domain_str or re.search(r'[a-zA-Z]', domain_str)):        return True    return Falsedef probe_target_with_curl(domain: str, timeout: int = 4) -> Tuple[bool, float, str]:    """    Проверяет доступность домена через системный curl.exe (принцип ZapretAutoTuner и blockcheck).    Отправляет реальный HTTPS-запрос через winws и проверяет отклик HTTP сервера.    """    start_time = time.time()    url = f"https://{domain}/"    if "googlevideo" in domain:        url = f"https://{domain}/generate_204"    null_device = "NUL" if os.name == 'nt' else "/dev/null"    curl_bin = "curl.exe" if os.name == 'nt' else "curl"    cmd = [        curl_bin,        "-4",        "-s",        "-o", null_device,        "-w", "%{http_code}",        "--connect-timeout", "3",        "--max-time", str(timeout),        "-k",        "-A",        "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Safari/537.36",        url    ]    try:        if os.name == 'nt':            res = subprocess.run(                cmd,                stdout=subprocess.PIPE,                stderr=subprocess.DEVNULL,                text=True,                creationflags=subprocess.CREATE_NO_WINDOW,                timeout=timeout + 2            )        else:            res = subprocess.run(                cmd,                stdout=subprocess.PIPE,                stderr=subprocess.DEVNULL,                text=True,                timeout=timeout + 2            )        elapsed = (time.time() - start_time) * 1000.0        output = res.stdout.strip() if res.stdout else ""        if res.returncode == 0 and output.isdigit() and int(output) > 0:            return True, round(elapsed, 1), f"HTTP {output}"        elif res.returncode == 0:            return True, round(elapsed, 1), "CURL OK"        else:            return False, 0.0, f"FAIL (exit {res.returncode})"    except Exception:        return False, 0.0, "TIMEOUT"@dataclassclass WinwsParams:    tcp_split: int = 1    tcp_seqovl: int = 664    tcp_ttl: int = 0    udp_repeats: int = 8    udp_cutoff: str = "n4"    def to_key(self) -> Tuple[int, int, int, int, str]:        return (self.tcp_split, self.tcp_seqovl, self.tcp_ttl, self.udp_repeats, self.udp_cutoff)class FuzzerEngine:    def __init__(self,                 bat_path: str = "general (ALT11).bat",                 log_callback: Optional[Callable[[str], None]] = None,                 status_callback: Optional[Callable[[dict], None]] = None,                 require_100_percent: bool = False):        self.bat_path = bat_path        self.log_callback = log_callback or print        self.status_callback = status_callback        self.require_100_percent = require_100_percent        self.min_success_ratio = 1.0 if require_100_percent else 0.5        self.is_running = False        self.target_hosts: List[str] = []    def log(self, text: str):        if self.log_callback:            self.log_callback(text)    def set_status(self, **kwargs):        if self.status_callback:            self.status_callback(kwargs)    @staticmethod    def flush_dns_cache():        """Автоматическая очистка кэша DNS в Windows."""        try:            if os.name == 'nt':                subprocess.run("ipconfig /flushdns", shell=True, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)        except Exception:            pass    @staticmethod    def is_winws_alive() -> bool:        try:            output = subprocess.check_output('tasklist /FI "IMAGENAME eq winws.exe"', shell=True,                                             stderr=subprocess.DEVNULL)            return b"winws.exe" in output        except subprocess.CalledProcessError:            return False    @staticmethod    def stop_winws():        """Остановка процесса winws.exe."""        os.system("taskkill /F /IM winws.exe >nul 2>&1")    @staticmethod    def reset_windivert():        """Очистка и сброс драйвера WinDivert при сбоях."""        os.system("taskkill /F /IM winws.exe >nul 2>&1")        if os.name == 'nt':            os.system("net stop WinDivert >nul 2>&1")            os.system("sc stop WinDivert >nul 2>&1")    @staticmethod    def start_winws(bat_path: str) -> bool:        """Запуск службы winws по выбранному батнику."""        if not os.path.exists(bat_path):            return False        FuzzerEngine.stop_winws()        time.sleep(0.5)        try:            if os.name == 'nt':                subprocess.Popen(["cmd.exe", "/c", bat_path], creationflags=subprocess.CREATE_NO_WINDOW)            else:                subprocess.Popen(["/bin/sh", bat_path])            time.sleep(2.5)            return FuzzerEngine.is_winws_alive()        except Exception:            return False    def sync_hosts_to_user_list(self, hosts: List[str]):        r"""        Синхронизирует доменные имена со ВСЕМИ списками .txt в папке lists        (включая list-general.txt, list-general-user.txt, list-discord.txt, list-youtube.txt),        чтобы winws.exe фильтровал и применял правила обхода DPI к этим адресам независимо от настроек батника.        """        try:            bat_dir = os.path.dirname(os.path.abspath(self.bat_path)) if os.path.dirname(self.bat_path) else os.getcwd()            lists_dir = os.path.join(bat_dir, "lists")            if not os.path.exists(lists_dir):                os.makedirs(lists_dir, exist_ok=True)            target_files = [os.path.join(lists_dir, "list-general-user.txt")]            for fname in ["list-general.txt", "list-discord.txt", "list-youtube.txt"]:                fpath = os.path.join(lists_dir, fname)                if os.path.exists(fpath):                    target_files.append(fpath)            for user_list_path in target_files:                existing_lines = []                existing_hosts = set()                if os.path.exists(user_list_path):                    with open(user_list_path, 'r', encoding='utf-8', errors='ignore') as f:                        for line in f:                            line_str = line.strip()                            if line_str and not line_str.startswith("#"):                                existing_hosts.add(line_str.lower())                            existing_lines.append(line_str)                added_count = 0                for h in hosts:                    cleaned = h.strip().lower()                    if cleaned and is_valid_domain(cleaned) and cleaned not in existing_hosts:                        existing_hosts.add(cleaned)                        existing_lines.append(cleaned)                        added_count += 1                if added_count > 0 or not os.path.exists(user_list_path):                    with open(user_list_path, 'w', encoding='utf-8') as f:                        for line in existing_lines:                            if line:                                f.write(line + "\n")                    self.log(                        f"  [+] Синхронизировано {added_count} новых доменов в '{os.path.basename(user_list_path)}'")        except Exception as e:            self.log(f"  [!] Ошибка синхронизации списков хостов: {e}")    @classmethod    def sanitize_and_filter_targets(cls, targets: List[str]) -> List[str]:        valid_targets = []        seen = set()        for raw_target in targets:            cleaned = raw_target.strip().lower()            if not cleaned or cleaned in seen:                continue            try:                ipaddress.ip_address(cleaned)                continue            except ValueError:                pass            if is_valid_domain(cleaned):                valid_targets.append(cleaned)                seen.add(cleaned)        return valid_targets    def extract_baseline(self) -> WinwsParams:        if not os.path.exists(self.bat_path):            raise FileNotFoundError(f"Файл '{self.bat_path}' не найден!")        with open(self.bat_path, 'r', encoding='utf-8', errors='ignore') as f:            content = f.read()        def get_val(pattern: str, default: int | str):            match = re.search(pattern, content)            return type(default)(match.group(1)) if match else default        return WinwsParams(            tcp_split=get_val(r'--dpi-desync-split-pos=(\d+)', 1),            tcp_seqovl=get_val(r'--dpi-desync-split-seqovl=(\d+)', 664),            tcp_ttl=get_val(r'--dpi-desync-ttl=(\d+)', 0),            udp_repeats=get_val(r'--dpi-desync-repeats=(\d+)', 8),            udp_cutoff=get_val(r'--dpi-desync-cutoff=([a-z0-9]+)', 'n4')        )    def generate_mutations(self, baseline: WinwsParams) -> Generator[WinwsParams, None, None]:        """Умный стратег мутаций с приоритетными синергетическими комбинациями."""        visited: Set[Tuple[int, int, int, int, str]] = set()        visited.add(baseline.to_key())        POS_RANGE = (1, 2, 3, 4, 5, 6)        TTL_RANGE = (3, 4, 5, 7)        TTL_EXT_RANGE = (3, 4, 5, 7, 8)        SEQ_RANGE = (681, 500, 300, 800, 1000, 1200, 100)        CUTOFF_RANGE = ("n2", "n3", "d2", "d3", "d4")        REPEATS_RANGE = (6, 10, 12, 15, 4)        priority_combos = [            WinwsParams(tcp_split=2, tcp_seqovl=681, tcp_ttl=3, udp_repeats=6, udp_cutoff="n3"),            WinwsParams(tcp_split=3, tcp_seqovl=681, tcp_ttl=4, udp_repeats=8, udp_cutoff="d2"),            WinwsParams(tcp_split=2, tcp_seqovl=500, tcp_ttl=3, udp_repeats=10, udp_cutoff="n2"),            WinwsParams(tcp_split=4, tcp_seqovl=800, tcp_ttl=5, udp_repeats=6, udp_cutoff="d3"),            WinwsParams(tcp_split=1, tcp_seqovl=300, tcp_ttl=3, udp_repeats=12, udp_cutoff="n4"),            WinwsParams(tcp_split=3, tcp_seqovl=1000, tcp_ttl=7, udp_repeats=8, udp_cutoff="d4"),        ]        for combo in priority_combos:            key = combo.to_key()            if key not in visited:                visited.add(key)                yield combo        for pos in POS_RANGE:            for ttl in TTL_RANGE:                mutated = copy.copy(baseline)                mutated.tcp_split = pos                mutated.tcp_ttl = ttl                key = mutated.to_key()                if key not in visited:                    visited.add(key)                    yield mutated        for seq in SEQ_RANGE:            if seq != baseline.tcp_seqovl:                mutated = copy.copy(baseline)                mutated.tcp_seqovl = seq                key = mutated.to_key()                if key not in visited:                    visited.add(key)                    yield mutated        for pos in POS_RANGE:            if pos != baseline.tcp_split:                mutated = copy.copy(baseline)                mutated.tcp_split = pos                key = mutated.to_key()                if key not in visited:                    visited.add(key)                    yield mutated        for ttl in TTL_EXT_RANGE:            if ttl != baseline.tcp_ttl:                mutated = copy.copy(baseline)                mutated.tcp_ttl = ttl                key = mutated.to_key()                if key not in visited:                    visited.add(key)                    yield mutated        for cutoff in CUTOFF_RANGE:            if cutoff != baseline.udp_cutoff:                mutated = copy.copy(baseline)                mutated.udp_cutoff = cutoff                key = mutated.to_key()                if key not in visited:                    visited.add(key)                    yield mutated        for repeats in REPEATS_RANGE:            if repeats != baseline.udp_repeats:                mutated = copy.copy(baseline)                mutated.udp_repeats = repeats                key = mutated.to_key()                if key not in visited:                    visited.add(key)                    yield mutated    def create_and_run_temp_bat(self, params: WinwsParams) -> str:        temp_bat = "_fuzzer_temp.bat"        with open(self.bat_path, 'r', encoding='utf-8', errors='ignore') as f:            lines = f.readlines()        clean_content = ""        for line in lines:            line_lower = line.strip().lower()            if line_lower.startswith("call service.bat status_zapret") or line_lower.startswith(                    "call service.bat check_updates"):                continue            clean_content += line        clean_content = re.sub(r'--dpi-desync-split-seqovl=\d+', f'--dpi-desync-split-seqovl={params.tcp_seqovl}',                               clean_content)        clean_content = re.sub(r'--dpi-desync-split-pos=\d+', f'--dpi-desync-split-pos={params.tcp_split}',                               clean_content)        clean_content = re.sub(r'--dpi-desync-repeats=\d+', f'--dpi-desync-repeats={params.udp_repeats}', clean_content)        clean_content = re.sub(r'--dpi-desync-cutoff=[a-z0-9]+', f'--dpi-desync-cutoff={params.udp_cutoff}',                               clean_content)        if params.tcp_ttl > 0 and "--dpi-desync-ttl" not in clean_content:            clean_content = re.sub(r'(--dpi-desync-split-pos=\d+)', rf'\1  --dpi-desync-ttl={params.tcp_ttl}',                                   clean_content)        elif params.tcp_ttl > 0:            clean_content = re.sub(r'--dpi-desync-ttl=\d+', f'--dpi-desync-ttl={params.tcp_ttl}', clean_content)        with open(temp_bat, 'w', encoding='utf-8') as f:            f.write(clean_content)        subprocess.run(["cmd.exe", "/c", temp_bat], stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)        return temp_bat    def _evaluate_config_sync(self, target_domains: List[str]) -> Tuple[int, List[Tuple[str, bool, float, str]]]:        """        Многопоточная проверка целей через системный curl.exe (принцип ZapretAutoTuner).        """        passed_count = 0        results = []        with concurrent.futures.ThreadPoolExecutor(max_workers=8) as executor:            future_to_domain = {                executor.submit(probe_target_with_curl, dom, 4): dom                for dom in target_domains            }            for future in concurrent.futures.as_completed(future_to_domain):                if not self.is_running:                    break                domain = future_to_domain[future]                try:                    passed, latency, proto = future.result()                    if passed:                        passed_count += 1                    results.append((domain, passed, latency, proto))                except Exception:                    results.append((domain, False, 0.0, "FAIL"))        return passed_count, results    def evaluate_config(self, params: WinwsParams, target_domains: List[str], label: str = "МУТАЦИЯ",                        min_success_ratio: Optional[float] = None) -> bool:        if min_success_ratio is None:            min_success_ratio = getattr(self, 'min_success_ratio', 0.5)        self.log(f"\n[*] ТЕСТИРУЕМ: {label}")        self.log(f"    TCP: split={params.tcp_split}, seqovl={params.tcp_seqovl}, ttl={params.tcp_ttl}")        self.log(f"    UDP: repeats={params.udp_repeats}, cutoff={params.udp_cutoff}")        self.log(            f"    Цели ({len(target_domains)}): {', '.join(target_domains[:6])}{'...' if len(target_domains) > 6 else ''}")        self.set_status(params=params, current_step=label)        temp_bat = self.create_and_run_temp_bat(params)        time.sleep(2.5)        if not self.is_winws_alive():            self.log("  [!] ОШИБКА: Процесс winws.exe мгновенно завершился.")            if os.path.exists(temp_bat):                os.remove(temp_bat)            return False        total_hosts = len(target_domains)        required_success = max(1, int(math.ceil(total_hosts * min_success_ratio)))        self.log(f"  [~] Валидация пробива через curl.exe (требуется: {required_success}/{total_hosts})...")        start_time = time.time()        try:            passed_count, results = self._evaluate_config_sync(target_domains)        except Exception as e:            self.log(f"  [!] Ошибка выполнения проверки: {e}")            passed_count, results = 0, []        for domain, passed, latency, proto in results:            if passed:                status_str = f"[O] Доступен ({proto}, {latency:.0f} ms)"            else:                status_str = "[X] Заблокирован"            self.log(f"      -> {domain:35} {status_str}")        elapsed = time.time() - start_time        is_success = passed_count >= required_success        result_icon = "[+]" if is_success else "[-]"        self.log(            f"  {result_icon} Результат: {passed_count}/{total_hosts} доступно за {elapsed:.1f} сек. (порог: {required_success})")        self.log("  [*] Очистка среды...")        self.stop_winws()        time.sleep(0.8)        if os.path.exists(temp_bat):            os.remove(temp_bat)        return is_success    def patch_original_bat(self, params: WinwsParams):        backup_path = self.bat_path + ".bak"        if not os.path.exists(backup_path):            shutil.copy2(self.bat_path, backup_path)            self.log(f"\n[i] Создан бэкап: {backup_path}")        with open(self.bat_path, 'r', encoding='utf-8', errors='ignore') as f:            content = f.read()        content = re.sub(r'--dpi-desync-split-seqovl=\d+', f'--dpi-desync-split-seqovl={params.tcp_seqovl}', content)        content = re.sub(r'--dpi-desync-split-pos=\d+', f'--dpi-desync-split-pos={params.tcp_split}', content)        content = re.sub(r'--dpi-desync-repeats=\d+', f'--dpi-desync-repeats={params.udp_repeats}', content)        content = re.sub(r'--dpi-desync-cutoff=[a-z0-9]+', f'--dpi-desync-cutoff={params.udp_cutoff}', content)        if params.tcp_ttl > 0 and "--dpi-desync-ttl" not in content:            content = re.sub(r'(--dpi-desync-split-pos=\d+)', rf'\1  --dpi-desync-ttl={params.tcp_ttl}', content)        elif params.tcp_ttl > 0:            content = re.sub(r'--dpi-desync-ttl=\d+', f'--dpi-desync-ttl={params.tcp_ttl}', content)        with open(self.bat_path, 'w', encoding='utf-8') as f:            f.write(content)        self.log(f"  [+] Конфиг '{os.path.basename(self.bat_path)}' успешно обновлен рабочими параметрами!")    def run_single_test(self, params: WinwsParams, target_domains: List[str]) -> bool:        """Запуск разовой проверки конкретного набора параметров."""        self.is_running = True        try:            self.log("=== Zapret Fuzzer Engine: Разовый тест ===")            cleaned_targets = self.sanitize_and_filter_targets(target_domains)            if not cleaned_targets:                self.log("[!] Ошибка: Передан пустой или некорректный список хостов.")                self.set_status(state="FAILED", message="Некорректные цели")                return False            self.sync_hosts_to_user_list(cleaned_targets)            FuzzerEngine.flush_dns_cache()            self.target_hosts = cleaned_targets            min_ratio = getattr(self, 'min_success_ratio', 0.5)            success = self.evaluate_config(params, cleaned_targets, label="РАЗОВЫЙ ТЕСТ", min_success_ratio=min_ratio)            if success:                self.set_status(state="SUCCESS", message="Разовый тест прошел успешно!", params=params)            else:                self.set_status(state="FAILED", message="Разовый тест не прошел")            return success        except Exception as e:            self.log(f"\n[!] Ошибка во время разового теста: {e}")            self.set_status(state="ERROR", message=str(e))            return False        finally:            self.is_running = False    def run_fuzzing(self, target_domains: List[str]):        self.is_running = True        try:            self.log("=== Zapret Fuzzer Engine (v5 ZapretAutoTuner Engine) ===")            self.log(f"Всего целевых доменов/хостов: {len(target_domains)}")            cleaned_targets = self.sanitize_and_filter_targets(target_domains)            if not cleaned_targets:                self.log("[!] Ошибка: Передан пустой или некорректный список хостов.")                self.set_status(state="FAILED", message="Некорректные цели")                return False            self.log("[*] Синхронизация доменных хостов со всеми файлами списков...")            self.sync_hosts_to_user_list(cleaned_targets)            self.log("[*] Очистка кэша DNS (ipconfig /flushdns)...")            FuzzerEngine.flush_dns_cache()            self.log(f"[+] Валидация списка завершена: {len(cleaned_targets)} уникальных доменов подлежат проверке.")            self.target_hosts = cleaned_targets            baseline = self.extract_baseline()            min_ratio = getattr(self, 'min_success_ratio', 0.5)            self.log(f"Базовый конфиг извлекается из '{self.bat_path}'...")            if self.evaluate_config(baseline, cleaned_targets, label="БАЗОВЫЙ КОНФИГ", min_success_ratio=min_ratio):                self.log("\n[+] Базовый конфиг РАБОТАЕТ. Мутации не требуются.")                self.set_status(state="SUCCESS", message="Базовый конфиг работает!")                return True            self.log("\n[-] Базовый конфиг не сработал. Запуск эвристического подбора мутаций...")            for i, mutation in enumerate(self.generate_mutations(baseline), 1):                if not self.is_running:                    self.log("\n[!] Подбор остановлен пользователем.")                    self.set_status(state="STOPPED", message="Остановлено пользователем")                    return False                if self.evaluate_config(mutation, cleaned_targets, label=f"МУТАЦИЯ #{i}", min_success_ratio=min_ratio):                    self.log("\n[+] УСПЕХ! Найден оптимальный профиль параметров.")                    self.patch_original_bat(mutation)                    self.set_status(state="SUCCESS", message="Рабочая стратегия найдена и сохранена!", params=mutation)                    return True            self.log("\n[-] Все возможные мутации проверены. Рабочая стратегия не найдена.")            self.set_status(state="FAILED", message="Мутации исчерпаны")            return False        except Exception as e:            self.log(f"\n[!] Ошибка во время фуззинга: {e}")            self.set_status(state="ERROR", message=str(e))            return False        finally:            self.is_running = False    def stop(self):        self.is_running = False        self.stop_winws()